interface Payment { type: string; amount: number }
function process(payment: any) {
  if (payment.type === 'card') {
    chargeCard(payment)
  } else if (payment.type === 'paypal') {
    chargePaypal(payment)
  } else {
    throw new Error('Unknown')
  }
}

type RendererType = 'svg' | 'canvas' | 'webgl'
function render(shape: any, type: RendererType) {
  switch (type) {
    case 'svg': return svgRender(shape)
    case 'canvas': return canvasRender(shape)
    case 'webgl': return webglRender(shape)
  }
}

